function insert(intervals: number[][], newInterval: number[]): number[][] {
  const result: number[][] = [];
  let [start, end] = newInterval;
  let i = 0;
  const n = intervals.length;

  // 1. Интервалы, которые целиком ЛЕВЕЕ нового (кончаются до его начала)
  while (i < n && intervals[i][1] < start) {
    result.push(intervals[i]);
    i++;
  }

  // 2. Интервалы, пересекающиеся с новым (начинаются не позже его конца) —
  //    поглощаем их, расширяя границы нового интервала
  while (i < n && intervals[i][0] <= end) {
    start = Math.min(start, intervals[i][0]);
    end = Math.max(end, intervals[i][1]);
    i++;
  }
  result.push([start, end]);

  // 3. Интервалы, которые целиком ПРАВЕЕ нового, — копируем как есть
  while (i < n) {
    result.push(intervals[i]);
    i++;
  }

  return result;
}

// Время: O(n) — один проход, сортировка не нужна
// Память: O(n) — ответ
